import { expect, it } from "vitest";
import { headroom } from "../src/headroom";
import { shown } from "../src/pairs";
import { EQ, flatEQ, sameEQ } from "../src/types";
import vectors from "./fixtures/parity.json";

// Generated by the Python backend (tests/test_parity.py); the panel must compute the same values.
it("computes the backend's headroom for random equalizers", () => {
  for (const { eq, expected } of vectors.headroom) {
    const actual = headroom(eq as EQ);
    expect(actual.compensation).toBeCloseTo(expected.compensation, 3);
    expect(actual.effective_preamp).toBeCloseTo(expected.effective_preamp, 3);
  }
});

it("plays every frequency the backend keeps within 20 Hz–20 kHz, and shows the rest as flat placeholders", () => {
  for (const { expected } of vectors.frequency) {  // The backend snaps 0–20 Hz and 20–24 kHz onto the bounds.
    const eq = flatEQ();
    eq.bands[5] = { type: "peaking", frequency: expected, gain: 12, q: 1 };
    expect(shown(eq, 5) === eq.bands[5]).toBe(expected >= 20 && expected <= 20000);
  }
});

it("starts from the backend's flat preset", () => {
  expect(sameEQ(flatEQ(), vectors.flat as EQ)).toBe(true);
});
